<!-- WARNING: 本项目专属“粘人精”，严禁出现 Kiro、Krio、周棋洛等任何相关英文或拼音命名！ -->
<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { globalSettings } from '../../store/global'
import { getSecureValue, isNativeMobileApp, setSecureValue } from '../../services/mobileSecureStorage'
import { downloadWebVideo, type VideoConnectionMode } from '../../services/videoHttp'
import { H3_CN_BASE_URL,H3_GLOBAL_BASE_URL,H3_MODES,H3_RATIOS,cancelH3Task,createH3Task,downloadH3Video,estimateH3Cost,queryH3Task,regenerateH3Task,removeH3VideoFile,shareH3Video,validateH3Input,type H3Input,type H3Media,type H3Mode,type H3Ratio,type H3Resolution,type H3Role } from '../../services/minimaxH3Video'
import { useMinimaxH3History,type H3LocalTask } from '../../composables/useMinimaxH3History'

defineEmits<{(event:'back'):void}>()
const nativeApp=isNativeMobileApp()
const read=(key:string,fallback:string)=>localStorage.getItem(key)||fallback
const connectionMode=ref<VideoConnectionMode>((nativeApp?read('app_h3_connection','app'):'web') as VideoConnectionMode)
const rememberKey=ref(read('app_h3_remember_key','false')==='true')
const apiKey=ref(rememberKey.value?read('app_h3_web_key',''):'')
const webSessionKey=ref(apiKey.value)
const keyReady=ref(false),showKey=ref(false),showSettings=ref(false),busy=ref(false)
const activeTab=ref<'create'|'works'|'materials'>('create'),notice=ref(''),errorText=ref('')
const prompt=ref(read('app_h3_prompt','')),chatExcerpt=ref('')
const projectName=ref(read('app_h3_project','默认作品集')),projectFilter=ref('全部')
const mode=ref<H3Mode>('text'),media=ref<H3Media[]>([])
const config=reactive({baseUrl:read('app_h3_base_url',H3_CN_BASE_URL),resolution:read('app_h3_resolution','768P') as H3Resolution,ratio:read('app_h3_ratio','16:9') as H3Ratio,duration:Number(read('app_h3_duration','5')),watermark:read('app_h3_watermark','false')==='true'})
const savedPrompts=ref<Array<{name:string;prompt:string}>>(JSON.parse(read('app_h3_prompt_library','[]')))
const pollers=new Map<string,AbortController>()
const {tasks,load,save,patch,get,remove}=useMinimaxH3History()
const templates=[
  {name:'角色日常',text:'近景拍摄角色自然地看向镜头，轻声打招呼，动作细腻，环境光柔和，保留人物外观与服装特征。'},
  {name:'双人互动',text:'两名角色自然交流并产生细微表情变化，镜头缓慢横移，保持双方外观、声音与空间关系稳定。'},
  {name:'动态封面',text:'电影感动态封面，主体保持居中，背景产生层次视差，标题区域保持干净，最后定格为完整构图。'},
  {name:'动作参考',text:'人物参考视频中的动作节奏和运镜，保持参考图片中的身份、服装和面部特征，动作自然且符合物理规律。'}
]
const input=computed<H3Input>(()=>({prompt:prompt.value,mode:mode.value,resolution:config.resolution,ratio:config.ratio,duration:config.duration,watermark:config.watermark,media:media.value}))
const globalEndpoint=computed(()=>/minimax\.io/i.test(config.baseUrl))
const cost=computed(()=>estimateH3Cost(input.value,globalEndpoint.value))
const currency=computed(()=>globalEndpoint.value?'$':'¥')
const activeTasks=computed(()=>tasks.value.filter(t=>['submitting','queued','running'].includes(t.status)))
const projectNames=computed(()=>Array.from(new Set(tasks.value.map(task=>task.project||'默认作品集'))))
const visibleTasks=computed(()=>projectFilter.value==='全部'?tasks.value:tasks.value.filter(task=>(task.project||'默认作品集')===projectFilter.value))
const canUseApp=computed(()=>connectionMode.value==='web'||nativeApp)
const videoElements=new Map<string,HTMLVideoElement>()

watch([connectionMode,rememberKey],()=>{localStorage.setItem('app_h3_connection',connectionMode.value);localStorage.setItem('app_h3_remember_key',String(rememberKey.value));if(!rememberKey.value)localStorage.removeItem('app_h3_web_key')})
watch(config,value=>{localStorage.setItem('app_h3_base_url',value.baseUrl);localStorage.setItem('app_h3_resolution',value.resolution);localStorage.setItem('app_h3_ratio',value.ratio);localStorage.setItem('app_h3_duration',String(value.duration));localStorage.setItem('app_h3_watermark',String(value.watermark))},{deep:true})
watch(prompt,value=>localStorage.setItem('app_h3_prompt',value))
watch(projectName,value=>localStorage.setItem('app_h3_project',value))
watch(apiKey,value=>{if(connectionMode.value==='web'){webSessionKey.value=value;if(rememberKey.value)localStorage.setItem('app_h3_web_key',value)}})
watch(connectionMode,async value=>{try{apiKey.value=value==='web'?(rememberKey.value?read('app_h3_web_key',webSessionKey.value):webSessionKey.value):nativeApp?(await getSecureValue('minimax_h3_api_key'))||'':''}catch(error){errorText.value=error instanceof Error?error.message:'无法读取 API Key'}})
watch(mode,value=>{if(['first','last','frames'].includes(value))config.ratio='adaptive';else if(config.ratio==='adaptive'&&value==='text')config.ratio='16:9'})

const clear=()=>{notice.value='';errorText.value=''}
const client=()=>({apiKey:apiKey.value,baseUrl:config.baseUrl,connectionMode:connectionMode.value})
const taskClient=(task:H3LocalTask)=>({apiKey:apiKey.value,baseUrl:task.baseUrl,connectionMode:task.connectionMode})
const fileData=(file:File)=>new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('素材读取失败'));reader.readAsDataURL(file)})
const mediaRole=(kind:string):H3Role=>kind as H3Role
const changeMode=(value:H3Mode)=>{if(mode.value!==value)media.value=[];mode.value=value}
const addFiles=async(role:H3Role,event:Event)=>{clear();const element=event.target as HTMLInputElement;try{for(const file of Array.from(element.files||[])){const url=await fileData(file);media.value.push({id:crypto.randomUUID(),role,url,label:file.name,size:file.size})}}catch(error){errorText.value=error instanceof Error?error.message:'素材读取失败'}finally{element.value=''}}
const addUrl=(role:H3Role)=>media.value.push({id:crypto.randomUUID(),role,url:'',label:'外部素材'})
const allowedRoles=computed<H3Role[]>(()=>mode.value==='first'?['first_frame']:mode.value==='last'?['last_frame']:mode.value==='frames'?['first_frame','last_frame']:mode.value==='references'?['reference_image','reference_video','reference_audio']:[])
const applyTemplate=(value:string)=>{prompt.value=value;notice.value='已填入创作模板，可以继续修改。'}
const insertChat=()=>{if(!chatExcerpt.value.trim())return;prompt.value=`根据以下对话创作自然的视频场景，保留人物关系、情绪和关键台词：\n${chatExcerpt.value.trim()}`;chatExcerpt.value='';notice.value='聊天片段已整理到视频描述中。'}
const savePrompt=()=>{if(!prompt.value.trim())return;const name=`方案 ${savedPrompts.value.length+1}`;savedPrompts.value.push({name,prompt:prompt.value.trim()});localStorage.setItem('app_h3_prompt_library',JSON.stringify(savedPrompts.value));notice.value='已保存为常用创作方案。'}
const bindVideo=(id:string,element:any)=>{if(element)videoElements.set(id,element as HTMLVideoElement);else videoElements.delete(id)}
const captureFrame=(task:H3LocalTask)=>{clear();try{const video=videoElements.get(task.id);if(!video?.videoWidth)throw new Error('请先播放到想保留的画面');const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;const context=canvas.getContext('2d');if(!context)throw new Error('当前设备无法截取画面');context.drawImage(video,0,0);const url=canvas.toDataURL('image/jpeg',.92);mode.value='references';media.value=[{id:crypto.randomUUID(),role:'reference_image',url,label:`${task.id}-画面.jpg`,size:Math.round(url.length*.75)}];activeTab.value='create';notice.value='当前画面已放入参考图片。'}catch(error){errorText.value=error instanceof Error?`${error.message}；如果视频源限制跨域读取，请先下载后作为本地素材选择。`:'无法截取画面'}}

const wait=(ms:number,signal:AbortSignal)=>new Promise<void>((resolve,reject)=>{const timer=setTimeout(resolve,ms);signal.addEventListener('abort',()=>{clearTimeout(timer);reject(new DOMException('已停止','AbortError'))},{once:true})})
const poll=async(localId:string)=>{if(pollers.has(localId))return;const controller=new AbortController();pollers.set(localId,controller);try{const row=await get(localId);const remoteId=row?.remoteId;if(!remoteId)return;if(row.connectionMode!==connectionMode.value)throw new Error(`请切换到${row.connectionMode==='web'?'网页直连':'App 直连'}后继续查询`);while(!controller.signal.aborted){const remote=await queryH3Task(taskClient(row),remoteId);if(remote.status==='succeeded'){await patch(localId,{status:'completed',videoUrl:remote.url,enhancedPrompt:remote.prompt,usage:remote.usage,error:''});return}if(remote.status==='failed'||remote.status==='cancelled'){await patch(localId,{status:remote.status==='failed'?'failed':'cancelled',error:remote.error||'任务未完成'});return}await patch(localId,{status:remote.status,error:''});await wait(8000,controller.signal)}}catch(error){if((error as Error)?.name!=='AbortError'){await patch(localId,{status:'paused',error:error instanceof Error?error.message:'查询中断'}).catch(()=>{});errorText.value=error instanceof Error?error.message:'查询中断'}}finally{pollers.delete(localId)}}
const submit=async(kind:'generation'|'context'='generation')=>{clear();if(!canUseApp.value){errorText.value='App 直连需要在安装后的 App 中使用';return}busy.value=true;const id=`h3_${Date.now()}_${Math.random().toString(36).slice(2,7)}`;try{validateH3Input(input.value);await save({id,type:kind,status:'submitting',createdAt:Date.now(),updatedAt:Date.now(),baseUrl:config.baseUrl,connectionMode:connectionMode.value,project:projectName.value.trim()||'默认作品集',input:JSON.parse(JSON.stringify(input.value))});const remoteId=await createH3Task(client(),input.value,kind);await patch(id,{remoteId,status:'queued'});notice.value=kind==='context'?'正在理解素材并完善描述。':'任务已提交，可以离开页面后回来继续查询。';void poll(id)}catch(error){await patch(id,{status:'failed',error:error instanceof Error?error.message:'提交失败'}).catch(()=>{});errorText.value=error instanceof Error?error.message:'提交失败'}finally{busy.value=false}}
const doRegenerate=async(task:H3LocalTask)=>{clear();busy.value=true;const id=`h3_reg_${Date.now()}`;try{if(!task.remoteId)throw new Error('原作品没有云端任务编号');const remoteId=await regenerateH3Task(client(),task.remoteId,config.watermark);await save({id,remoteId,type:'regeneration',status:'queued',createdAt:Date.now(),updatedAt:Date.now(),baseUrl:config.baseUrl,connectionMode:connectionMode.value,project:task.project,input:task.input});notice.value='2K 再生成任务已提交。';void poll(id)}catch(error){errorText.value=error instanceof Error?error.message:'再生成失败'}finally{busy.value=false}}
const stop=async(task:H3LocalTask)=>{if(!task.remoteId)return;clear();try{if(task.connectionMode!==connectionMode.value)throw new Error(`请切换到${task.connectionMode==='web'?'网页直连':'App 直连'}后取消任务`);await cancelH3Task(taskClient(task),task.remoteId);pollers.get(task.id)?.abort();await patch(task.id,{status:'cancelled'});notice.value='排队任务已取消。'}catch(error){errorText.value=error instanceof Error?error.message:'当前任务不能取消'}}
const resume=(task:H3LocalTask)=>{clear();if(task.connectionMode!==connectionMode.value){errorText.value=`请先在连接设置中切换到${task.connectionMode==='web'?'网页直连':'App 直连'}`;return}if(!apiKey.value.trim()){errorText.value='请先填写对应连接方式的 API Key';return}void patch(task.id,{status:'queued',error:''}).then(()=>poll(task.id))}
const reuse=(task:H3LocalTask)=>{prompt.value=task.input.prompt;mode.value=task.input.mode;Object.assign(config,{resolution:task.input.resolution,ratio:task.input.ratio,duration:task.input.duration,watermark:task.input.watermark});media.value=JSON.parse(JSON.stringify(task.input.media));projectName.value=task.project||'默认作品集';activeTab.value='create';notice.value='已带入描述、参数和保留的创作素材。'}
const useEnhanced=(task:H3LocalTask)=>{if(task.enhancedPrompt){prompt.value=task.enhancedPrompt;activeTab.value='create';notice.value='已带入增强描述，可以修改后生成。'}}
const saveKey=async()=>{clear();if(connectionMode.value==='app'){if(!nativeApp){errorText.value='请在安装后的 App 中保存系统密钥';return}await setSecureValue('minimax_h3_api_key',apiKey.value.trim());notice.value='API Key 已保存到系统安全存储。'}else{if(rememberKey.value)localStorage.setItem('app_h3_web_key',apiKey.value);notice.value=rememberKey.value?'网页密钥已保存在当前浏览器。':'网页密钥仅在当前页面会话中使用。'}}
const downloadTask=async(task:H3LocalTask)=>{clear();if(!task.videoUrl)return;if(connectionMode.value==='web'){downloadWebVideo(task.videoUrl,`${task.id}.mp4`);return}try{if(task.localFileUri){await shareH3Video(task.localFileUri);return}const file=await downloadH3Video(task.id,task.videoUrl);await patch(task.id,{localFilePath:file.path,localFileUri:file.uri,localWebUrl:file.webUrl});await shareH3Video(file.uri)}catch(error){errorText.value=error instanceof Error?error.message:'视频保存失败'}}
const deleteTask=async(task:H3LocalTask)=>{await removeH3VideoFile(task.localFilePath);await remove(task.id)}
onMounted(async()=>{await load();if(nativeApp&&connectionMode.value==='app')apiKey.value=(await getSecureValue('minimax_h3_api_key'))||'';keyReady.value=true;for(const task of activeTasks.value)void poll(task.id)})
onUnmounted(()=>pollers.forEach(item=>item.abort()))
</script>

<template>
  <div class="h3-hall" :class="{dark:globalSettings.darkMode}">
    <header><button class="icon" @click="$emit('back')">‹</button><div><h1>MiniMax H3</h1><p>多模态参考与原生立体声音画创作</p></div><button class="icon" @click="showSettings=!showSettings">⚙</button></header>
    <nav><button :class="{active:activeTab==='create'}" @click="activeTab='create'">创作</button><button :class="{active:activeTab==='works'}" @click="activeTab='works'">作品 <b v-if="tasks.length">{{tasks.length}}</b></button><button :class="{active:activeTab==='materials'}" @click="activeTab='materials'">灵感</button></nav>
    <main>
      <p v-if="notice" class="notice">{{notice}}</p><p v-if="errorText" class="error">{{errorText}}</p>
      <section v-if="showSettings" class="panel settings">
        <h2>连接设置</h2><div class="choice"><button :class="{active:connectionMode==='web'}" @click="connectionMode='web'">网页直连</button><button :class="{active:connectionMode==='app'}" @click="connectionMode='app'">App 直连</button></div>
        <label>接入站点<select v-model="config.baseUrl"><option :value="H3_CN_BASE_URL">国内开放平台</option><option :value="H3_GLOBAL_BASE_URL">国际开放平台</option></select></label>
        <label>API Key<div class="row"><input v-model="apiKey" :type="showKey?'text':'password'" autocomplete="off" placeholder="填写 MiniMax API Key"><button @click="showKey=!showKey">{{showKey?'隐藏':'显示'}}</button></div></label>
        <label v-if="connectionMode==='web'" class="check"><input v-model="rememberKey" type="checkbox">记住在当前浏览器；关闭后仍可恢复任务</label>
        <small>{{connectionMode==='web'?'浏览器直接请求所选 MiniMax 接口，不经过本站后端。':'密钥写入 Android/iOS 系统安全存储。'}}</small><button class="primary" :disabled="!keyReady" @click="saveKey">保存连接设置</button>
      </section>
      <template v-if="activeTab==='create'">
        <section class="panel"><div class="heading"><div><small>创作方式</small><h2>{{H3_MODES.find(i=>i.value===mode)?.description}}</h2></div><strong>{{currency}}{{cost}}</strong></div><div class="choice scroll"><button v-for="item in H3_MODES" :key="item.value" :class="{active:mode===item.value}" @click="changeMode(item.value)">{{item.label}}</button></div>
          <div v-if="allowedRoles.length" class="assets"><div v-for="role in allowedRoles" :key="role" class="asset"><b>{{role==='first_frame'?'首帧':role==='last_frame'?'尾帧':role==='reference_image'?'参考图片':role==='reference_video'?'参考视频':'参考音频'}}</b><label>选择本地文件<input type="file" :accept="role==='reference_video'?'video/mp4,video/quicktime':role==='reference_audio'?'audio/wav,audio/mpeg':'image/jpeg,image/png,image/webp,image/heic,image/heif'" :multiple="role.startsWith('reference_')" @change="addFiles(mediaRole(role),$event)"></label><button @click="addUrl(mediaRole(role))">添加地址</button></div></div>
          <div v-for="item in media" :key="item.id" class="media-row"><span>{{item.label}}</span><input v-model="item.url" placeholder="素材地址或本地数据"><input v-if="item.role==='reference_video'||item.role==='reference_audio'" v-model.number="item.duration" type="number" min="2" max="15" placeholder="秒"><button @click="media=media.filter(i=>i.id!==item.id)">×</button></div>
        </section>
        <section class="panel"><div class="heading"><div><small>视频描述</small><h2>主体、场景、动作、镜头与声音</h2></div><span>{{prompt.length}}/7000</span></div><textarea v-model="prompt" rows="7" placeholder="描述目标视频以及每项参考素材的用途"></textarea><div class="chips"><button v-for="item in templates" :key="item.name" @click="applyTemplate(item.text)">{{item.name}}</button><button @click="savePrompt">保存方案</button></div>
          <div class="grid"><label>分辨率<select v-model="config.resolution"><option>768P</option><option>2K</option></select></label><label>比例<select v-model="config.ratio" :disabled="['first','last','frames'].includes(mode)"><option v-for="ratio in H3_RATIOS" :key="ratio">{{ratio}}</option></select></label><label>时长<select v-model.number="config.duration"><option v-for="n in 12" :key="n" :value="n+3">{{n+3}} 秒</option></select></label><label>作品集<input v-model="projectName" maxlength="40" placeholder="默认作品集"></label><label class="check"><input v-model="config.watermark" type="checkbox">AIGC 水印</label></div>
          <div class="actions"><button class="primary" :disabled="busy||!apiKey.trim()||!canUseApp" @click="submit('generation')">{{busy?'提交中…':`生成 H3 视频 · 预计 ${currency}${cost}`}}</button><button :disabled="busy||!apiKey.trim()" @click="submit('context')">理解素材并完善描述</button></div>
        </section>
      </template>
      <section v-else-if="activeTab==='materials'" class="panel"><h2>灵感与常用方案</h2><div class="template" v-for="item in templates" :key="item.name"><b>{{item.name}}</b><p>{{item.text}}</p><button @click="applyTemplate(item.text);activeTab='create'">使用</button></div><div class="template" v-for="item in savedPrompts" :key="item.name"><b>{{item.name}}</b><p>{{item.prompt}}</p><button @click="applyTemplate(item.prompt);activeTab='create'">使用</button></div><h2>从聊天片段整理场景</h2><textarea v-model="chatExcerpt" rows="6" placeholder="粘贴用户主动选中的聊天内容"></textarea><button class="primary" @click="insertChat">整理为视频描述</button></section>
      <section v-else class="works"><section v-if="tasks.length" class="panel work-filter"><label>作品集<select v-model="projectFilter"><option>全部</option><option v-for="name in projectNames" :key="name">{{name}}</option></select></label></section><article v-for="task in visibleTasks" :key="task.id" class="panel work"><video v-if="task.videoUrl||task.localWebUrl" :ref="element=>bindVideo(task.id,element)" :src="task.localWebUrl||task.videoUrl" controls playsinline></video><div class="heading"><div><small>{{task.project||'默认作品集'}} · {{task.type==='context'?'提示词理解':task.type==='regeneration'?'2K 再生成':'视频生成'}}</small><h2>{{task.status}}</h2></div><span>{{new Date(task.createdAt).toLocaleString()}}</span></div><p>{{task.error||task.input.prompt}}</p><div class="actions"><button v-if="task.videoUrl" @click="downloadTask(task)">{{task.localFileUri?'分享/保存':'下载'}}</button><button v-if="task.videoUrl" @click="captureFrame(task)">截取当前画面</button><button v-if="task.enhancedPrompt" @click="useEnhanced(task)">采用增强描述</button><button v-if="task.status==='completed'&&task.input.resolution==='768P'" @click="doRegenerate(task)">再生成为 2K</button><button v-if="['queued','running'].includes(task.status)" @click="stop(task)">取消</button><button v-if="['paused','queued','running'].includes(task.status)" @click="resume(task)">继续查询</button><button @click="reuse(task)">复用</button><button @click="deleteTask(task)">删除</button></div></article><p v-if="!visibleTasks.length" class="empty">当前作品集还没有 H3 作品</p></section>
    </main>
  </div>
</template>

<style scoped>
.h3-hall{--bg:#f7f7f5;--card:#fff;--soft:#efefec;--text:#1d1d1f;--sub:#777;position:absolute;inset:0;z-index:1000;display:flex;flex-direction:column;background:var(--bg);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","Microsoft YaHei",sans-serif}.dark{--bg:#19191b;--card:#242426;--soft:#303033;--text:#f4f4f1;--sub:#aaa}header{display:flex;align-items:center;gap:12px;padding:calc(env(safe-area-inset-top) + 12px) 18px 10px}header>div{min-width:0;flex:1;text-align:center}h1,h2,p{margin:0}header h1{font-size:20px}header p{margin-top:4px;color:var(--sub);font-size:11px}.icon{width:36px;height:36px;border:0;border-radius:50%;background:transparent;color:inherit;font-size:22px}nav{display:flex;gap:5px;margin:0 18px 10px;padding:3px;border-radius:12px;background:var(--soft)}nav button{flex:1;padding:8px;border:0;border-radius:9px;background:transparent;color:var(--sub)}nav button.active{background:var(--card);color:var(--text)}main{flex:1;overflow:auto;padding:0 18px calc(28px + env(safe-area-inset-bottom))}.panel{margin-bottom:12px;padding:14px;border:1px solid rgba(127,127,127,.15);border-radius:17px;background:var(--card)}.panel h2{font-size:14px}.notice,.error{margin-bottom:10px;padding:10px;border-radius:11px;font-size:11px}.notice{background:#eaf6ed;color:#397148}.error{background:#fff0f0;color:#b64242}.heading{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:11px}.heading small{color:var(--sub);font-size:9px}.heading strong{padding:5px 8px;border-radius:10px;background:var(--soft);font-size:10px}.choice{display:flex;gap:6px}.choice.scroll{overflow-x:auto;margin-bottom:12px}.choice button,.chips button,.actions button,.asset button,.asset label,.template button,.row button{padding:8px 10px;border:0;border-radius:10px;background:var(--soft);color:inherit;white-space:nowrap}.choice button.active,.primary{background:var(--text)!important;color:var(--bg)!important}.settings{display:grid;gap:11px}.settings 